{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목에 관한 근거를 실제 개선 방식의 선택으로 연결할 수 있는지 확인한다. 질문은 쿼리 개선 방식을 정한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회가 느렸던 상황이다.",
          "task": "조회 지연의 원인에 맞는 쿼리 개선 방식을 정해야 했다.",
          "action": "실행 계획과 조회 구조에서 확인한 사실을 근거로 개선 방식을 선택한 판단을 설명한다.",
          "result": "확인한 병목과 선택한 개선 방식 사이의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "쿼리 개선 방식을 선택한 구체적인 근거",
          "그 근거가 된 실행 계획이나 조회 구조의 관찰 사실",
          "선택한 개선 방식이 관찰된 병목을 줄이는 이유"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 시간을 3.2초에서 0.4초로 줄이셨던데요, 쿼리 개선 방식은 무엇을 근거로 정하셨어요?",
      "answerTip": "당시 경험을 차분하게 떠올려 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "개선 방식의 선택 근거를 실행 계획이나 조회 구조에서 관찰한 사실로 구체적으로 설명한다.",
            "선택한 방식이 해당 병목을 줄이는 이유를 관찰 사실과 일관되게 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "개선 방식의 선택 근거와 관련 관찰 사실을 제시하지만, 관찰 내용이 구체적이지 않다.",
            "선택한 방식과 병목의 관련성은 설명하지만, 병목이 줄어드는 이유에 대한 연결이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "수정한 내용이나 성능 수치만 말하고 개선 방식을 선택한 근거를 제시하지 못한다.",
            "관찰 사실이 없거나, 제시한 사실과 개선 방식 사이의 연결이 타당하지 않다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류에서 확인한 원인을 실제 오류 차단 조치로 연결할 수 있는지 확인한다. 질문은 스케줄러 중복 실행을 막기 위해 잠금 키를 선택한 이유에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 후 알림이 중복 발송되는 오류가 발생했다.",
          "task": "두 서버의 스케줄러 중복 실행을 막을 조치를 선택해야 했다.",
          "action": "로그에서 확인한 중복 실행 양상을 근거로 잠금 키를 선택한 이유를 설명한다.",
          "result": "확인한 오류 원인과 잠금 키를 통한 차단 방식의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "스케줄러 중복 실행을 막는 조치로 잠금 키를 선택한 이유",
          "선택의 근거가 된 두 서버의 동시 실행에 관한 로그 관찰 사실",
          "잠금 키가 해당 동시 실행으로 인한 중복 발송을 막는 원리"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 수정하셨던데요, 스케줄러 중복 실행을 막는 조치로 잠금 키를 선택하신 이유는 뭐였어요?",
      "answerTip": "본인이 했던 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "잠금 키를 선택한 이유를 두 서버의 동시 실행에 관한 구체적인 로그 관찰 사실과 연결한다.",
            "잠금 키가 확인된 중복 실행을 제어해 중복 발송을 막는 원리를 일관되게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "두 서버의 동시 실행을 잠금 키 선택의 이유로 제시하지만, 근거가 된 로그 관찰 내용이 부족하다.",
            "잠금 키로 중복 실행을 막는다는 설명은 있으나, 해당 오류를 차단하는 원리가 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금 키를 사용했다는 사실만 말하고 선택 이유나 근거가 된 관찰 사실을 제시하지 못한다.",
            "잠금 키의 작동 설명이 확인된 중복 실행 원인과 연결되지 않거나 타당하지 않다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "현업 요청을 실제 구현 범위로 구체화하는 판단을 검증한다. 인터뷰로 파악한 요구사항 중 당시 구현할 범위를 정한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 인터뷰를 바탕으로 예약 서비스의 요구사항 정의서를 작성한 상황이다.",
          "task": "수집한 요구사항을 바탕으로 당시 구현할 기능의 범위를 정해야 했다.",
          "action": "요청의 목적과 제약을 근거로 구현 범위의 경계를 정한 판단을 설명한다.",
          "result": "어떤 요청을 어떤 근거로 구현 범위에 포함하거나 제외했는지가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "당시 구현 범위를 정한 구체적인 판단 근거",
          "그 근거가 된 세탁소의 요청 목적이나 구현 제약",
          "해당 근거가 기능의 포함 또는 제외 결정으로 이어진 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳의 인터뷰로 요구사항 정의서를 쓰셨던데요, 당시 구현 범위는 무엇을 근거로 정하셨어요?",
      "answerTip": "기억나는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구현 범위를 정한 판단 근거를 구체적으로 제시한다.",
            "판단 근거를 실제 세탁소 요청의 목적이나 구현 제약으로 뒷받침한다.",
            "그 근거에 따라 어떤 기능을 포함하거나 제외했는지 일관되게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현 범위를 정한 근거는 제시하지만 요청 목적이나 구현 제약에 대한 설명이 제한적이다.",
            "기능의 포함 또는 제외 결정은 드러나지만 판단 근거와의 연결이 일부 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항을 수집하거나 문서를 작성했다는 설명에 머물러 구현 범위의 판단 근거가 드러나지 않는다.",
            "요청 목적이나 구현 제약이 실제 범위 결정과 연결되지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 구현 가능한 화면 동작으로 구체화하는 판단을 검증한다. 화면설계서에 담은 예외 화면의 설계 결정 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "예약 서비스의 기능 흐름과 예외 상황을 화면설계서에 담은 상황이다.",
          "task": "특정 예외 상황에서 화면이 보여 줄 상태나 동작을 정해야 했다.",
          "action": "가장 고민한 예외 화면의 설계 결정과 그 결정이 다루는 발생 조건 및 화면 동작을 설명한다.",
          "result": "선택한 예외 상황에서 화면이 어떤 상태나 동작을 제공하도록 설계되었는지 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "예외 화면에서 가장 고민한 구체적인 설계 결정",
          "해당 결정이 다루는 예외 상황의 발생 조건",
          "그 조건에 대응하도록 정한 화면 상태나 동작과 설계 결정의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 예외 상황을 담은 화면설계서 28장을 작성하셨던데요, 그중 예외 화면에서 가장 고민하신 설계 결정은 무엇이었어요?",
      "answerTip": "한 장면에 집중해 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 화면에서 고민한 설계 결정 하나를 구체적으로 제시한다.",
            "해당 예외가 발생하는 조건을 명확하게 설명한다.",
            "발생 조건에 대응하는 화면 상태나 동작을 구체화하여 설계 결정과 일관되게 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 화면의 설계 결정은 제시하지만 발생 조건에 대한 설명이 제한적이다.",
            "화면 상태나 동작은 일부 드러나지만 예외 조건과의 연결이 충분히 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "화면설계서의 분량이나 작성 도구만 설명하고 예외 화면의 설계 결정을 제시하지 못한다.",
            "예외 발생 조건과 화면 상태나 동작이 불분명하여 어떤 설계를 했는지 확인하기 어렵다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 그대로 수행하지 않고 투약을 보류하는 판단을 검증한다. 평소와 다른 진통제 용량을 투약 중단으로 연결한 이유에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 용량이 평소의 두 배로 처방된 상황이다.",
          "task": "처방의 정확성이 확인되지 않은 상태에서 투약 진행 여부를 판단해야 했다.",
          "action": "처방 용량에서 발견한 이상과 확인되지 않은 투약의 위험을 근거로 투약을 보류한 이유를 설명한다.",
          "result": "처방의 불확실성이 해소되기 전까지 투약하지 않기로 한 판단 근거가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "처방 확인 전 투약을 보류한 이유",
          "당시 처방 용량을 의심하게 된 구체적인 사실",
          "발견한 용량 차이가 확인 없는 투약의 위험으로 이어진다고 판단한 연결 근거"
        ]
      },
      "question": "푸른결종합병원에서 진통제 용량이 평소의 두 배로 처방된 적이 있으셨던데요, 당시 처방 확인이 끝나기 전까지 투약을 보류한 이유는 뭐였어요?",
      "answerTip": "당시 상황을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "당시 처방에서 발견한 용량 차이를 구체적으로 설명한다.",
            "용량 차이로 처방의 정확성을 확신할 수 없었으며, 확인 없는 투약이 환자에게 위험할 수 있다는 점을 보류 이유로 명확히 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 다른 용량 때문에 투약을 보류했다는 핵심 이유는 설명한다.",
            "용량 차이와 투약 위험의 연결 근거는 구체성이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 보류한 이유나 처방을 의심한 사실을 설명하지 못한다.",
            "입력 오류였다는 사후 사실만 반복해 당시 보류 판단의 근거가 드러나지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태 변화를 담당의에게 지체 없이 보고할 필요성과 연결하는 판단을 검증한다. 활력징후와 통증 변화 중 즉시 보고할 대상을 정하는 기준에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 전후 환자의 활력징후와 통증을 관찰하던 업무 상황이다.",
          "task": "관찰한 상태 변화가 담당의에게 즉시 보고할 사안인지 판단해야 했다.",
          "action": "관찰된 수치나 증상 변화와 환자의 기존 상태를 근거로 즉시 보고 여부를 판단한 기준을 설명한다.",
          "result": "즉시 보고 대상으로 판단한 상태 변화와 그 판단 기준이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "담당의에게 바로 보고할 상태 변화를 정한 판단 기준",
          "그 기준을 적용한 활력징후 또는 통증 변화의 구체적인 양상",
          "관찰한 변화가 환자 상태의 악화 가능성이나 긴급성을 뜻한다고 판단한 근거"
        ]
      },
      "question": "푸른결종합병원 정형외과 병동에서 활력징후와 통증을 관찰하셨던데요, 담당의에게 바로 보고할 상태 변화는 무엇을 기준으로 판단하셨어요?",
      "answerTip": "기억나는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "즉시 보고할 상태 변화를 정한 기준을 구체적으로 설명한다.",
            "실제 관찰한 활력징후 또는 통증 변화의 양상을 제시하고, 그 변화가 악화 가능성이나 긴급성을 나타낸다고 본 근거를 명확히 연결한다."
          ]
        },
